INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20825$nota-0100$m20825$, $m20826$Training and Racing with a Power Meter.pdf$m20826$, $m20827$290$m20827$, $m20828$HOW TO SUCCESSFULLY IMPLEMENT A POWER-BASED TRAINING PLAN: 1. Find your functional threshold power... 2. Use your FTP to establish your training levels. 3. Try out sample workouts and collect data on your power meter. 4. Understand your data and what the charts/graphs are telling you. 5. Use your Power Profile, Power Duration Curve, and Quadrant Analysis to pinpoint your strengths and weaknesses. 6. Assess your time constraints. 7. Develop a power-based training plan that targets the improvements you need to reach your goal. 8. Review your power data regularly for feedback on your training. 9. Adjust your FTP and training levels as your fitness progresses. 10. Refine your plan as needed to get additional rest or adaptation.$m20828$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20829$nota-0100$m20829$, $m20830$nota-0001$m20830$, $m20831$complementa$m20831$, $m20832$consolida em sequência os conceitos centrais (FTP, zonas, Power Profile, PDC, Quadrant Analysis) já detalhados individualmente em notas anteriores$m20832$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20833$nota-0106$m20833$, $m20834$Training and Racing with a Power Meter.pdf$m20834$, $m20835$306$m20835$, $m20836$You may notice that the areas you train in shift throughout the season. In the off-season, you might spend more time in Level 2 (Endurance), for example, and as spring approaches, you might spend more time in Levels 3 (Tempo) and 4 (Lactate Threshold).$m20836$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20837$nota-0106$m20837$, $m20838$Training and Racing with a Power Meter.pdf$m20838$, $m20839$307$m20839$, $m20840$In this example, the rider spent the majority of his time in Levels 1, 2, and 3 (Active Recovery, Endurance, and Tempo), just building a base of fitness... the rider is now spending more time at Level 3 (Tempo) and also in Level 5 (VO2max) and Level 6 (Anaerobic Capacity).$m20840$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20841$nota-0106$m20841$, $m20842$Training and Racing with a Power Meter.pdf$m20842$, $m20843$310$m20843$, $m20844$By June, the amount of time he spends in Level 6 (Anaerobic Capacity) is really increasing... Also note the drastic increase in the amount of time that he spends in Level 1 (Active Recovery)... The chart for July shows how much racing influences the amount of time spent at or near FTP. The big step-down after Level 4 (Lactate Threshold) is clearly evident now.$m20844$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20845$nota-0106$m20845$, $m20846$nota-0048$m20846$, $m20847$pre-requisito$m20847$, $m20848$usa as 7 zonas clássicas de Coggan (nota-0048 e correlatas) como base do cálculo de tempo-em-zona$m20848$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20849$nota-0115$m20849$, $m20850$Training and Racing with a Power Meter.pdf$m20850$, $m20851$341$m20851$, $m20852$As a triathlete, you will need to make three Performance Manager Charts inside the TrainingPeaks WKO Software: a PMC just for cycling, a PMC just for running, and then a combination PMC to include both running and cycling. This will allow you to get a better understanding of which workouts in which sports give you the best results in peak fitness... and finally, which sport contributes the most to the overall picture for you as a percentage of training stress.$m20852$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20853$nota-0115$m20853$, $m20854$nota-0083$m20854$, $m20855$pre-requisito$m20855$, $m20856$aplica o conceito de PMC/CTL-ATL-TSB (Cap.9) separadamente por esporte e de forma combinada$m20856$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20857$nota-0115$m20857$, $m20858$nota-0114$m20858$, $m20859$pre-requisito$m20859$, $m20860$requer rTSS (nota-0114) para computar a carga de treino da corrida na mesma escala do TSS de bike$m20860$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20861$nota-0129$m20861$, $m20862$Training and Racing with a Power Meter.pdf$m20862$, $m20863$377$m20863$, $m20864$In any sport, a great recipe for properly utilizing a power meter is to: 1. Determine the demands of the event by recording the power data and the effort that it takes to complete the event successfully. 2. Understand your strengths and weaknesses relative to the demands of the event. 3. Train for both the demands of the event and your weaknesses... 4. Review the results of those training sessions and compare them with data collected in races.$m20864$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20865$nota-0129$m20865$, $m20866$nota-0100$m20866$, $m20867$complementa$m20867$, $m20868$versão mais genérica e enxuta do protocolo de 10 passos (nota-0100), aplicável a qualquer modalidade (não só estrada)$m20868$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20869$nota-0143$m20869$, $m20870$Training and Racing with a Power Meter.pdf$m20870$, $m20871$400$m20871$, $m20872$Step 1: Collect Data and Determine Your Threshold Power... Remember to repeat this test every six to eight weeks, or whenever you think your fitness has changed.$m20872$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20873$nota-0143$m20873$, $m20874$nota-0021$m20874$, $m20875$complementa$m20875$, $m20876$reforça, no fechamento do livro, a cadência recomendada de reteste de FTP (nota-0021) como parte do ciclo geral de uso do medidor de potência$m20876$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20877$nota-0149$m20877$, $m20878$Manual treinamento.pdf$m20878$, $m20879$11$m20879$, $m20880$praticamente todas as decisões de treinamento podem ser resumidas a quatro perguntas: 1. O que limita a performance deste atleta? 2. Como essa limitação pode ser medida? 3. Qual adaptação fisiológica deve ser desenvolvida? 4. Qual estratégia de treinamento apresenta maior probabilidade de produzir essa adaptação?$m20880$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m20881$nota-0178$m20881$, $m20882$Manual treinamento.pdf$m20882$, $m20883$86$m20883$, $m20884$Domínio Moderado: Abaixo do LT1. Homeostase mantida. Grande utilização de gordura. Baixa fadiga. Domínio Pesado: Entre LT1 e LT2... Domínio Severo: Acima do LT2. Não existe estado estável. VO₂ continua aumentando. Fadiga inevitável. Domínio Extremo: Intensidades máximas. Predomínio dos sistemas anaeróbios. Tempo de sustentação muito reduzido.$m20884$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20885$nota-0178$m20885$, $m20886$nota-0022$m20886$, $m20887$alternativa-a$m20887$, $m20888$modelo fisiológico de 4 domínios (baseado em LT1/LT2) descreve a mesma faixa de intensidades que os 7 níveis práticos de Coggan (%FTP) do Livro 1, mas com granularidade e critério de corte diferentes — ambos válidos, não conflitantes, mas não diretamente intercambiáveis$m20888$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20889$nota-0178$m20889$, $m20890$nota-0171$m20890$, $m20891$pre-requisito$m20891$, $m20892$LT1 é a fronteira entre os domínios Moderado e Pesado — citado no corpo da nota, link estrutural ausente até auditoria de 2026-08-02$m20892$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m20893$nota-0178$m20893$, $m20894$nota-0172$m20894$, $m20895$pre-requisito$m20895$, $m20896$LT2 é a fronteira entre os domínios Pesado e Severo — citado no corpo da nota, link estrutural ausente até auditoria de 2026-08-02$m20896$)
